"""Domain 1 - Plan and manage an Azure AI solution. Labs 1-2."""


def lab(num, topic, title, objective, desc, build, services, duration, prerequisites,
        steps, test, troubleshooting, challenge, reflection, checkpoint, deck_steps=None):
    return dict(
        num=num,
        topic=topic,
        title=title,
        objective=objective,
        desc=desc,
        build=build,
        services=services,
        duration=duration,
        prerequisites=prerequisites,
        steps=steps,
        test=test,
        troubleshooting=troubleshooting,
        challenge=challenge,
        reflection=reflection,
        checkpoint=checkpoint,
        deck_steps=deck_steps or [s[0] for s in steps[:4]],
    )


